cat > edge_check.cpp <<'EOF'
#include "all_your_base.h"
#include <cassert>
#include <stdexcept>
#include <vector>
using all_your_base::convert;
int main() {
    assert((convert(16, std::vector<unsigned int>{2,10}, 10) == std::vector<unsigned int>{4,2}));
    assert((convert(10, std::vector<unsigned int>{42}, 16) == std::vector<unsigned int>{2,10}));
    assert((convert(2, std::vector<unsigned int>{}, 10).empty()));
    assert((convert(7, std::vector<unsigned int>{0,6,0}, 10) == std::vector<unsigned int>{4,2}));
    assert((convert(1000, std::vector<unsigned int>{1,2,3}, 1000) == std::vector<unsigned int>{1,2,3}));
    assert((convert(36, std::vector<unsigned int>{35}, 10) == std::vector<unsigned int>{3,5}));
    bool threw = false;
    try { convert(1, std::vector<unsigned int>{}, 10); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    threw = false;
    try { convert(2, std::vector<unsigned int>{2}, 10); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    threw = false;
    try { convert(2, std::vector<unsigned int>{1}, 1); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    threw = false;
    try { convert(0, std::vector<unsigned int>{}, 0); } catch (const std::invalid_argument&) { threw = true; }
    assert(threw);
    return 0;
}
EOF
g++ -std=c++17 -Wall -Wextra -Wpedantic -Werror edge_check.cpp all_your_base.cpp -o edge_check && ./edge_check && echo EDGE_CHECKS_PASSED

cat > edge_check.cpp <<'EOF'
#include "all_your_base.h"
#include <cassert>
#include <cstdio>
#include <stdexcept>
#include <vector>
using all_your_base::convert;

#define CHECK(label, expr) do { std::printf("check: %s\n", label); assert(expr); } while (0)

int main() {
    CHECK("hex_to_dec", convert(16, std::vector<unsigned int>{2,10}, 10) == (std::vector<unsigned int>{4,2}));
    CHECK("dec_to_hex", convert(10, std::vector<unsigned int>{4,2}, 16) == (std::vector<unsigned int>{2,10}));
    CHECK("empty_in", convert(2, std::vector<unsigned int>{}, 10).empty());
    CHECK("leading_zeros", convert(7, std::vector<unsigned int>{0,6,0}, 10) == (std::vector<unsigned int>{4,2}));
    CHECK("base1000", convert(1000, std::vector<unsigned int>{1,2,3}, 1000) == (std::vector<unsigned int>{1,2,3}));
    CHECK("base36", convert(36, std::vector<unsigned int>{35}, 10) == (std::vector<unsigned int>{3,5}));

    bool threw = false;
    try { convert(1, std::vector<unsigned int>{}, 10); } catch (const std::invalid_argument&) { threw = true; }
    CHECK("first_base_one_throws", threw);

    threw = false;
    try { convert(2, std::vector<unsigned int>{2}, 10); } catch (const std::invalid_argument&) { threw = true; }
    CHECK("invalid_digit_throws", threw);

    threw = false;
    try { convert(2, std::vector<unsigned int>{1}, 1); } catch (const std::invalid_argument&) { threw = true; }
    CHECK("second_base_one_throws", threw);

    threw = false;
    try { convert(0, std::vector<unsigned int>{}, 0); } catch (const std::invalid_argument&) { threw = true; }
    CHECK("zero_bases_throw", threw);

    std::printf("EDGE_CHECKS_PASSED\n");
    return 0;
}
EOF
g++ -std=c++17 -Wall -Wextra -Wpedantic -Werror edge_check.cpp all_your_base.cpp -o edge_check && ./edge_check
